<style>
.sx-page{font-family:Inter,sans-serif;color:#25313C}.sx-head{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;margin-bottom:22px}.sx-title{font-size:23px;font-weight:700;color:#123B5D;margin:0}.sx-sub{font-size:13px;color:#64748B;margin:6px 0 0}.sx-actions{display:flex;gap:9px;flex-wrap:wrap}.sx-btn{display:inline-flex;align-items:center;justify-content:center;min-height:40px;padding:0 16px;border-radius:9px;border:1px solid #CBD5E1;background:#fff;color:#334155;font-size:13px;font-weight:600;text-decoration:none;cursor:pointer}.sx-btn.primary{background:#123B5D;border-color:#123B5D;color:#fff}.sx-panel,.sx-card{background:#fff;border:1px solid #CBD5E1;border-radius:15px;padding:18px;margin-bottom:16px}.sx-panel h3{font-size:15px;color:#123B5D;margin:0 0 14px;font-weight:700}.sx-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:18px}.sx-label{font-size:12px;color:#64748B;font-weight:600}.sx-value{font-size:27px;color:#123B5D;font-weight:700;margin-top:7px}.sx-table{width:100%;border-collapse:collapse}.sx-table th{text-align:left;background:#F8FAFC;color:#64748B;font-size:11px;padding:12px 10px}.sx-table td{font-size:13px;padding:12px 10px;border-top:1px solid #E2E8F0}.sx-muted{color:#64748B;font-size:12px}.sx-pill{display:inline-block;padding:4px 9px;border-radius:20px;background:#EFF6FF;color:#1D4ED8;font-size:11px;font-weight:700}.sx-pill.ok{background:#DCFCE7;color:#166534}.sx-pill.off{background:#F1F5F9;color:#475569}.sx-alert{padding:11px 13px;border-radius:9px;background:#F0FDF4;color:#166534;margin-bottom:14px;font-size:13px}.sx-error{background:#FEF2F2;color:#991B1B}.sx-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.sx-field label{display:block;font-size:12px;font-weight:650;margin-bottom:6px}.sx-field input,.sx-field select,.sx-field textarea{width:100%;border:1px solid #CBD5E1;border-radius:9px;padding:10px 12px;font:13px Inter,sans-serif}.sx-field textarea{min-height:100px}.sx-toolbar{display:flex;gap:9px;flex-wrap:wrap;margin-bottom:14px}.sx-toolbar input,.sx-toolbar select{border:1px solid #CBD5E1;border-radius:9px;padding:10px;font:13px Inter,sans-serif}.sx-empty{text-align:center;padding:22px;color:#64748B;font-size:13px}.sx-flow{display:flex;align-items:center;justify-content:center;gap:12px;flex-wrap:wrap;padding:20px;background:#F8FAFC;border-radius:12px}.sx-node{padding:13px 17px;background:#fff;border:1px solid #CBD5E1;border-radius:10px;font-size:12px;font-weight:700;color:#123B5D;box-shadow:0 3px 10px #0f172a0a}.sx-arrow{color:#176B87;font-size:20px;animation:sx-pulse 1.4s infinite}@keyframes sx-pulse{50%{opacity:.3;transform:translateX(4px)}}@media(max-width:850px){.sx-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.sx-head{display:block}.sx-actions{margin-top:12px}.sx-form{grid-template-columns:1fr}.sx-grid{grid-template-columns:1fr 1fr}.sx-table-wrap{overflow:auto}}
</style>